<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"typography":{"fontSize":"15px"},"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<p style="font-size:15px;margin-top:0px;margin-bottom:0px">材料費（品番と数量を明記します）</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"typography":{"fontSize":"15px"},"spacing":{"margin":{"top":"8px","bottom":"0px"}}}} -->
<p style="font-size:15px;margin-top:8px;margin-bottom:0px">職人の手間・工事の管理</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"typography":{"fontSize":"15px"},"spacing":{"margin":{"top":"8px","bottom":"0px"}}}} -->
<p style="font-size:15px;margin-top:8px;margin-bottom:0px">養生・工事中の片づけ・最終の清掃</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"typography":{"fontSize":"15px"},"spacing":{"margin":{"top":"8px","bottom":"0px"}}}} -->
<p style="font-size:15px;margin-top:8px;margin-bottom:0px">既存のものの解体と処分費</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"typography":{"fontSize":"15px"},"spacing":{"margin":{"top":"8px","bottom":"0px"}}}} -->
<p style="font-size:15px;margin-top:8px;margin-bottom:0px">足場（必要な工事のみ）</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"typography":{"fontSize":"15px"},"spacing":{"margin":{"top":"8px","bottom":"0px"}}}} -->
<p style="font-size:15px;margin-top:8px;margin-bottom:0px">近隣へのご挨拶</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"typography":{"fontSize":"15px"},"spacing":{"margin":{"top":"8px","bottom":"0px"}}}} -->
<p style="font-size:15px;margin-top:8px;margin-bottom:0px">お引き渡し後の1か月・1年・3年の点検</p>
<!-- /wp:paragraph --></div></div>
