<h3 class="has-text-align-center" style="font-size:17px;line-height:1.6;margin-top:0px;margin-bottom:12px">含まれないもの（別にかかります）</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"typography":{"fontSize":"15px"},"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<p style="font-size:15px;margin-top:0px;margin-bottom:0px">家具・家電の移動と一時保管</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"typography":{"fontSize":"15px"},"spacing":{"margin":{"top":"8px","bottom":"0px"}}}} -->
<p style="font-size:15px;margin-top:8px;margin-bottom:0px">エアコンの取り外し・取り付け（提携先をご紹介します）</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"typography":{"fontSize":"15px"},"spacing":{"margin":{"top":"8px","bottom":"0px"}}}} -->
<p style="font-size:15px;margin-top:8px;margin-bottom:0px">仮住まいの費用（まるごとの改修のとき）</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"typography":{"fontSize":"15px"},"spacing":{"margin":{"top":"8px","bottom":"0px"}}}} -->
<p style="font-size:15px;margin-top:8px;margin-bottom:0px">確認申請などの手数料（必要な工事のみ）</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"typography":{"fontSize":"15px"},"spacing":{"margin":{"top":"8px","bottom":"0px"}}}} -->
<p style="font-size:15px;margin-top:8px;margin-bottom:0px">壁を開けてから見つかった腐れ・シロアリの補修</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"typography":{"fontSize":"15px"},"spacing":{"margin":{"top":"8px","bottom":"0px"}}}} -->
<p style="font-size:15px;margin-top:8px;margin-bottom:0px">お客様がご用意される設備の保証</p>
